import { defineConfig } from 'vite';
export default defineConfig({server:{host:'127.0.0.1',port:5191,strictPort:true},plugins:[{name:'browser-media-protocol',transform(code,id){if(id.endsWith('/src/lib/emoji/catalog.ts'))return code.replace('edgelocal://emoji/','/emoji/');if(!id.includes('/src/components/') || !id.endsWith('.tsx')) return; return code.replace(/`edgelocal:\/\/\$\{item.data.imageId\}`/g,'item.data.preview').replace(/`edgelocal:\/\/\$\{img.imageId\}`/g,'img.preview').replace(/`edgelocal:\/\/file\/\$\{encodeURIComponent\(p.replace\(\/\\\\\/g, '\/'\)\)\}`/g,"((window as any).__previewFiles[p] || '')").replace(/e.preventDefault\(\)(\s+setInternalDragReq\(req\))/g,"e.dataTransfer.setData('text/x-edge-preview', JSON.stringify(req))$1");}}],build:{target:'esnext',rollupOptions:{input:'browser-preview.html'}}});
